# -*- coding: utf-8 -*-
# 자연소리 '지금 듣기 좋은' 카드 사진 5장 (사람이 앉아 듣는 그림) + 낮엔 파도·시냇물 하루씩 번갈아
import os, sys, base64

SCREEN = os.path.join('lib', 'screens', 'nature_sounds_screen.dart')
PUBSPEC = 'pubspec.yaml'
NAMES = ['morning', 'wave', 'stream', 'evening', 'night']

EDITS = [
    ('낮엔 파도·시냇물 하루씩 번갈아',
     "  /// 지금 시간에 어울리는 소리: 아침 새소리 · 낮 시냇물 · 저녁 모닥불 · 밤 빗소리\n",
     "  /// 지금 시간에 어울리는 소리: 아침 새소리 · 낮 파도·시냇물(하루씩 번갈아) · 저녁 모닥불 · 밤 빗소리\n"),
    ('낮 소리 고르기',
     "            ? '시냇물'\n",
     "            ? ((DateTime.now().millisecondsSinceEpoch ~/ 86400000).isEven ? '파도소리' : '시냇물')\n"),
    ('카드 사진 고르는 곳',
     "  /// 전체 탭 맨 위 사진 카드 (라디오 '지금 듣기 좋은' 카드와 같은 모양)\n",
     "  /// 카드 사진: 소리 종류별 그림 (사람이 앉아 듣는 장면)\n"
     "  static String _niceImage(String category) => switch (category) {\n"
     "        '새소리' => 'assets/nature_hero_morning.jpg',\n"
     "        '파도소리' => 'assets/nature_hero_wave.jpg',\n"
     "        '시냇물' => 'assets/nature_hero_stream.jpg',\n"
     "        '모닥불' => 'assets/nature_hero_evening.jpg',\n"
     "        _ => 'assets/nature_hero_night.jpg',\n"
     "      };\n\n"
     "  /// 전체 탭 맨 위 사진 카드 (라디오 '지금 듣기 좋은' 카드와 같은 모양)\n"),
    ('카드에 새 사진 넣기',
     "                  child: paranPhoto(\n"
     "                    _natureThumbImage(s.name, s.category, s.assetPath ?? ''),\n"
     "                    fit: BoxFit.cover,\n"
     "                    fallback: Container(color: soundColor),\n"
     "                  ),\n",
     "                  child: Image.asset(\n"
     "                    _niceImage(s.category),\n"
     "                    fit: BoxFit.cover,\n"
     "                    alignment: const Alignment(0, -0.2),\n"
     "                    cacheWidth: 800,\n"
     "                    errorBuilder: (_, __, ___) => Container(color: soundColor),\n"
     "                  ),\n"),
]

PUB_OLD = "    - assets/radio_hero_night.jpg\n"
PUB_NEW = PUB_OLD + ''.join("    - assets/nature_hero_%s.jpg\n" % n for n in NAMES)

IMAGES = {
    'morning': '',
    'wave': '',
    'stream': '',
    'evening': '',
    'night': '',
}


def load(p):
    with open(p, 'rb') as f:
        raw = f.read().decode('utf-8')
    return raw.replace('\r\n', '\n'), '\r\n' in raw


def main():
    for p in [SCREEN, PUBSPEC]:
        if not os.path.exists(p):
            print('❌ 파일을 못 찾았어요:', p, '— 아무것도 저장 안 했어요')
            sys.exit(1)
    text, crlf = load(SCREEN)
    if '_niceImage(' in text:
        print('이미 적용돼 있어요')
        return
    if '_natureNiceCard(' not in text:
        print('❌ apply_nature_nice_card.py 를 먼저 돌려 주세요 — 아무것도 저장 안 했어요')
        sys.exit(1)
    for name, old, new in EDITS:
        n = text.count(old)
        if n != 1:
            print('❌', name, '(찾은 개수: %d) — 아무것도 저장 안 했어요' % n)
            sys.exit(1)
        text = text.replace(old, new)
        print('✔', name)
    pub, pcrlf = load(PUBSPEC)
    if pub.count(PUB_OLD) != 1:
        print('❌ pubspec.yaml 에서 radio_hero_night 줄을 못 찾았어요 — 아무것도 저장 안 했어요')
        sys.exit(1)
    pub = pub.replace(PUB_OLD, PUB_NEW)
    print('✔ pubspec.yaml 에 사진 5장 등록')
    # 저장
    if crlf:
        text = text.replace('\n', '\r\n')
    with open(SCREEN, 'wb') as f:
        f.write(text.encode('utf-8'))
    if pcrlf:
        pub = pub.replace('\n', '\r\n')
    with open(PUBSPEC, 'wb') as f:
        f.write(pub.encode('utf-8'))
    os.makedirs('assets', exist_ok=True)
    for n in NAMES:
        with open(os.path.join('assets', 'nature_hero_%s.jpg' % n), 'wb') as f:
            f.write(base64.b64decode(IMAGES[n]))
        print('✔ 사진 넣었어요: assets/nature_hero_%s.jpg' % n)
    print('✔ 저장했어요')


main()
